cat << 'EOF' > /tmp/Program.cs
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild("/tmp/sv-c2ad8765d6aa425682febd2863364006/build.binlog");

Console.WriteLine($"Build succeeded: {build.Succeeded}");
Console.WriteLine();

// Find all errors
var errors = build.FindChildrenRecursive<Error>().ToList();
Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine();

foreach (var error in errors)
{
    var project = error.GetNearestParent<Project>();
    var projectName = project?.Name ?? "unknown";
    Console.WriteLine($"[{projectName}] {error.Code}: {error.Message}");
    if (!string.IsNullOrEmpty(error.File))
        Console.WriteLine($"  File: {error.File}({error.LineNumber},{error.ColumnNumber})");
    Console.WriteLine();
}

// Find all warnings
var warnings = build.FindChildrenRecursive<Warning>().ToList();
Console.WriteLine($"\nTotal warnings: {warnings.Count}");
foreach (var w in warnings.Take(20))
{
    var project = w.GetNearestParent<Project>();
    var projectName = project?.Name ?? "unknown";
    Console.WriteLine($"[{projectName}] {w.Code}: {w.Message}");
}
EOF
