using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild("/tmp/sv-c2ad8765d6aa425682febd2863364006/build.binlog");

Console.WriteLine("=== PROJECT BUILD RESULTS ===");
var projects = build.FindChildrenRecursive<Project>().ToList();
foreach (var p in projects)
{
    Console.WriteLine($"  {p.Name} => Succeeded: {p.Succeeded}");
}

Console.WriteLine("\n=== ALL ERRORS ===");
var errors = build.FindChildrenRecursive<Error>().ToList();
foreach (var error in errors)
{
    var project = error.GetNearestParent<Project>();
    Console.WriteLine($"[{project?.Name}] {error.Code}: {error.Text}");
    Console.WriteLine($"  File: {error.File}:{error.LineNumber}");
}

Console.WriteLine("\n=== SOURCE FILE CONTENT (if embedded) ===");
// Check for project references to understand dependency chain
var items = build.FindChildrenRecursive<Item>().Where(i => i.Name == "ProjectReference").ToList();
Console.WriteLine("\nProject References:");
foreach (var item in items)
{
    var project = item.GetNearestParent<Project>();
    Console.WriteLine($"  {project?.Name} -> {item.Text}");
}

// Check package references
var pkgs = build.FindChildrenRecursive<Item>().Where(i => i.Name == "PackageReference").ToList();
Console.WriteLine("\nPackage References:");
foreach (var pkg in pkgs)
{
    var project = pkg.GetNearestParent<Project>();
    Console.WriteLine($"  {project?.Name} -> {pkg.Text}");
}
EOF
