using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild("/tmp/sv-c2ad8765d6aa425682febd2863364006/build.binlog");

// Check if Api depends on Services (which failed)
Console.WriteLine("=== API PROJECT REFERENCES ===");
var tasks = build.FindChildrenRecursive<Task>().Where(t => t.Name == "Csc").ToList();
foreach (var task in tasks)
{
    var project = task.GetNearestParent<Project>();
    if (project?.Name != "Api.csproj") continue;

    var folder = task.FindChild<Folder>("Parameters");
    if (folder == null) continue;

    foreach (var child in folder.Children)
    {
        if (child is Parameter param && param.Name == "References")
        {
            Console.WriteLine("Api.csproj References (non-framework only):");
            foreach (var r in param.Children)
            {
                if (r is Item item && !item.Text.Contains("microsoft.netcore.app.ref"))
                    Console.WriteLine($"  {item.Text}");
            }
        }
    }
}

// Check if Api.csproj compiled successfully (has Csc task)
var apiCsc = tasks.Where(t => t.GetNearestParent<Project>()?.Name == "Api.csproj").ToList();
Console.WriteLine($"\nApi.csproj Csc invocations: {apiCsc.Count}");

// Look for MSB error about project dependency failures
Console.WriteLine("\n=== CHECKING FOR DEPENDENCY BUILD FAILURES ===");
var allMsgs = build.FindChildrenRecursive<Message>().Where(m => 
    m.Text != null && (m.Text.Contains("project reference") || m.Text.Contains("did not build"))).ToList();
foreach (var m in allMsgs)
    Console.WriteLine($"  {m.Text}");

// Reconstruct project files 
Console.WriteLine("\n=== TRYING RECONSTRUCT ===");
try {
    var dir = "/tmp/reconstructed";
    System.IO.Directory.CreateDirectory(dir);
    // The reconstruct subcommand from binlogtool should work
} catch (Exception ex) {
    Console.WriteLine($"Error: {ex.Message}");
}
